import{_ as n,c as a,a as e,o as p}from"./app-C_dHcy8Q.js";const i={};function l(t,s){return p(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="croupier-对象驱动的组件化后台管理系统" tabindex="-1"><a class="header-anchor" href="#croupier-对象驱动的组件化后台管理系统"><span>Croupier 对象驱动的组件化后台管理系统</span></a></h1><h2 id="📋-概述" tabindex="-1"><a class="header-anchor" href="#📋-概述"><span>📋 概述</span></a></h2><p>基于 JSON Schema 驱动的对象化游戏后台管理系统，实现了类似 Ant Design Pro 的低代码/无代码管理界面生成能力。</p><h2 id="🏗️-核心架构" tabindex="-1"><a class="header-anchor" href="#🏗️-核心架构"><span>🏗️ 核心架构</span></a></h2><h3 id="三层架构设计" tabindex="-1"><a class="header-anchor" href="#三层架构设计"><span>三层架构设计</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│                    UI Resource Layer                   │</span>
<span class="line">│  ┌─────────────────┐  ┌─────────────────┐              │</span>
<span class="line">│  │ player.resource │  │  item.resource  │  ...         │</span>
<span class="line">│  │   (ProTable)    │  │   (ProTable)    │              │</span>
<span class="line">│  └─────────────────┘  └─────────────────┘              │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line">                              │</span>
<span class="line">                              ▼</span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│                   Entity Definition Layer               │</span>
<span class="line">│  ┌─────────────────┐  ┌─────────────────┐              │</span>
<span class="line">│  │  player.entity  │  │   item.entity   │  ...         │</span>
<span class="line">│  │  (JSON Schema)  │  │  (JSON Schema)  │              │</span>
<span class="line">│  └─────────────────┘  └─────────────────┘              │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line">                              │</span>
<span class="line">                              ▼</span>
<span class="line">┌─────────────────────────────────────────────────────────┐</span>
<span class="line">│                    Function Layer                      │</span>
<span class="line">│  ┌─────────────────┐  ┌─────────────────┐              │</span>
<span class="line">│  │ player.register │  │  item.create    │  ...         │</span>
<span class="line">│  │ player.profile  │  │  item.list      │              │</span>
<span class="line">│  │ player.ban      │  │  item.update    │              │</span>
<span class="line">│  └─────────────────┘  └─────────────────┘              │</span>
<span class="line">└─────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="核心概念" tabindex="-1"><a class="header-anchor" href="#核心概念"><span>核心概念</span></a></h3><h4 id="_1-entity-实体" tabindex="-1"><a class="header-anchor" href="#_1-entity-实体"><span>1. Entity (实体)</span></a></h4><ul><li><strong>定义</strong>: 业务对象的完整描述，包含 JSON Schema、UI 配置、操作映射</li><li><strong>文件</strong>: <code>*.entity.json</code></li><li><strong>作用</strong>: 定义数据结构、验证规则、UI 展示方式</li><li><strong>示例</strong>: <code>player.entity.json</code>, <code>item.entity.json</code></li></ul><h4 id="_2-function-函数" tabindex="-1"><a class="header-anchor" href="#_2-function-函数"><span>2. Function (函数)</span></a></h4><ul><li><strong>定义</strong>: 具体的业务操作实现，包含输入输出 Schema、权限、语义</li><li><strong>文件</strong>: <code>*.json</code> (非 entity/resource 类型)</li><li><strong>作用</strong>: 实际的 CRUD 操作逻辑</li><li><strong>示例</strong>: <code>player.register.json</code>, <code>item.create.json</code></li></ul><h4 id="_3-resource-资源" tabindex="-1"><a class="header-anchor" href="#_3-resource-资源"><span>3. Resource (资源)</span></a></h4><ul><li><strong>定义</strong>: UI 层面的操作集合，将多个函数组合成完整的管理界面</li><li><strong>文件</strong>: <code>*.resource.json</code></li><li><strong>作用</strong>: 定义 ProTable 配置、列定义、操作按钮</li><li><strong>示例</strong>: <code>player.resource.json</code>, <code>item.resource.json</code></li></ul><h4 id="_4-component-组件" tabindex="-1"><a class="header-anchor" href="#_4-component-组件"><span>4. Component (组件)</span></a></h4><ul><li><strong>定义</strong>: 功能模块的打包单位，包含相关的 entities、functions、resources</li><li><strong>文件</strong>: <code>manifest.json</code></li><li><strong>作用</strong>: 模块化管理、依赖控制、安装/卸载</li><li><strong>示例</strong>: <code>player-management</code>, <code>item-management</code></li></ul><h2 id="🔧-技术实现" tabindex="-1"><a class="header-anchor" href="#🔧-技术实现"><span>🔧 技术实现</span></a></h2><h3 id="json-schema-驱动" tabindex="-1"><a class="header-anchor" href="#json-schema-驱动"><span>JSON Schema 驱动</span></a></h3><p>使用 JSON Schema 作为核心描述语言：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;object&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;properties&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;username&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;string&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;pattern&quot;</span><span class="token operator">:</span> <span class="token string">&quot;^[a-zA-Z0-9_]{3,16}$&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;description&quot;</span><span class="token operator">:</span> <span class="token string">&quot;用户名&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;searchable&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="对象绑定机制" tabindex="-1"><a class="header-anchor" href="#对象绑定机制"><span>对象绑定机制</span></a></h3><p>函数通过 <code>entity</code> 字段绑定到业务对象：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;player.register&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;entity&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;player&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;operation&quot;</span><span class="token operator">:</span> <span class="token string">&quot;create&quot;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="ui-自动生成" tabindex="-1"><a class="header-anchor" href="#ui-自动生成"><span>UI 自动生成</span></a></h3><p>基于 Entity 定义自动生成：</p><ul><li><strong>ProTable</strong>: 列表页面</li><li><strong>ProForm</strong>: 表单页面</li><li><strong>ProDescriptions</strong>: 详情页面</li></ul><h2 id="📁-目录结构" tabindex="-1"><a class="header-anchor" href="#📁-目录结构"><span>📁 目录结构</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">components/</span>
<span class="line">├── player-management/</span>
<span class="line">│   ├── manifest.json              # 组件清单</span>
<span class="line">│   └── descriptors/</span>
<span class="line">│       ├── player.entity.json     # 玩家实体定义</span>
<span class="line">│       ├── player.resource.json   # 玩家资源配置</span>
<span class="line">│       ├── player.register.json   # 注册函数</span>
<span class="line">│       ├── player.profile.get.json</span>
<span class="line">│       ├── player.profile.update.json</span>
<span class="line">│       ├── player.ban.json</span>
<span class="line">│       ├── player.unban.json</span>
<span class="line">│       └── player.list.json</span>
<span class="line">├── item-management/</span>
<span class="line">│   ├── manifest.json</span>
<span class="line">│   └── descriptors/</span>
<span class="line">│       ├── item.entity.json</span>
<span class="line">│       ├── item.resource.json</span>
<span class="line">│       ├── item.create.json</span>
<span class="line">│       ├── item.get.json</span>
<span class="line">│       ├── item.list.json</span>
<span class="line">│       ├── item.update.json</span>
<span class="line">│       └── item.delete.json</span>
<span class="line">└── economy-system/</span>
<span class="line">    ├── manifest.json</span>
<span class="line">    └── descriptors/</span>
<span class="line">        ├── currency.resource.json</span>
<span class="line">        ├── wallet.add.json</span>
<span class="line">        ├── wallet.deduct.json</span>
<span class="line">        └── wallet.get.json</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="🔄-工作流程" tabindex="-1"><a class="header-anchor" href="#🔄-工作流程"><span>🔄 工作流程</span></a></h2><h3 id="_1-定义实体-entity" tabindex="-1"><a class="header-anchor" href="#_1-定义实体-entity"><span>1. 定义实体 (Entity)</span></a></h3><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;player.entity&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;entity&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;schema&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token comment">/* JSON Schema */</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;operations&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;create&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;player.register&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;read&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;player.profile.get&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;update&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;player.profile.update&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;delete&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;player.ban&quot;</span><span class="token punctuation">]</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;ui&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;display_field&quot;</span><span class="token operator">:</span> <span class="token string">&quot;username&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;title_template&quot;</span><span class="token operator">:</span> <span class="token string">&quot;{username} ({nickname})&quot;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-实现函数-functions" tabindex="-1"><a class="header-anchor" href="#_2-实现函数-functions"><span>2. 实现函数 (Functions)</span></a></h3><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;player.register&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;entity&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;player&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;operation&quot;</span><span class="token operator">:</span> <span class="token string">&quot;create&quot;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;params&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token comment">/* 输入 Schema */</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;result&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token comment">/* 输出 Schema */</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;auth&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token comment">/* 权限控制 */</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-配置资源-resource" tabindex="-1"><a class="header-anchor" href="#_3-配置资源-resource"><span>3. 配置资源 (Resource)</span></a></h3><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;player.resource&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;resource&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;operations&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;create&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token property">&quot;function&quot;</span><span class="token operator">:</span> <span class="token string">&quot;player.register&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;read&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token property">&quot;function&quot;</span><span class="token operator">:</span> <span class="token string">&quot;player.profile.get&quot;</span><span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;ui&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;pro-table&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;columns&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span> <span class="token comment">/* 列定义 */</span> <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;actions&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;create&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;edit&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;delete&quot;</span><span class="token punctuation">]</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-打包组件-component" tabindex="-1"><a class="header-anchor" href="#_4-打包组件-component"><span>4. 打包组件 (Component)</span></a></h3><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;player-management&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;dependencies&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;functions&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span><span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;player.register&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">{</span><span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;player.profile.get&quot;</span><span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="🎯-系统优势" tabindex="-1"><a class="header-anchor" href="#🎯-系统优势"><span>🎯 系统优势</span></a></h2><h3 id="_1-低代码-无代码" tabindex="-1"><a class="header-anchor" href="#_1-低代码-无代码"><span>1. 低代码/无代码</span></a></h3><ul><li><strong>可视化配置</strong>: 通过管理界面创建和编辑实体</li><li><strong>自动生成UI</strong>: 基于 JSON Schema 自动生成表单和表格</li><li><strong>即插即用</strong>: 组件化安装和卸载</li></ul><h3 id="_2-类型安全" tabindex="-1"><a class="header-anchor" href="#_2-类型安全"><span>2. 类型安全</span></a></h3><ul><li><strong>输入验证</strong>: JSON Schema 验证所有输入</li><li><strong>输出类型</strong>: 明确的返回值类型定义</li><li><strong>编译时检查</strong>: 前端可以基于 Schema 生成 TypeScript 类型</li></ul><h3 id="_3-权限控制" tabindex="-1"><a class="header-anchor" href="#_3-权限控制"><span>3. 权限控制</span></a></h3><ul><li><strong>细粒度</strong>: 函数级别的权限控制</li><li><strong>灵活策略</strong>: 支持 RBAC 和 ABAC</li><li><strong>条件权限</strong>: <code>allow_if</code> 表达式支持</li></ul><h3 id="_4-可扩展性" tabindex="-1"><a class="header-anchor" href="#_4-可扩展性"><span>4. 可扩展性</span></a></h3><ul><li><strong>组件化</strong>: 模块独立开发和部署</li><li><strong>依赖管理</strong>: 自动解析组件依赖关系</li><li><strong>版本控制</strong>: 组件和函数的版本管理</li></ul><h2 id="📱-前端集成" tabindex="-1"><a class="header-anchor" href="#📱-前端集成"><span>📱 前端集成</span></a></h2><h3 id="protable-组件" tabindex="-1"><a class="header-anchor" href="#protable-组件"><span>ProTable 组件</span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token operator">&lt;</span>ResourceTable</span>
<span class="line">  resourceId<span class="token operator">=</span><span class="token string">&quot;player.resource&quot;</span></span>
<span class="line">  <span class="token comment">// 自动读取 /api/descriptors?id=player.resource</span></span>
<span class="line">  <span class="token comment">// 根据 operations 和 ui 配置生成界面</span></span>
<span class="line"><span class="token operator">/</span><span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="自动表单生成" tabindex="-1"><a class="header-anchor" href="#自动表单生成"><span>自动表单生成</span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token operator">&lt;</span>EntityForm</span>
<span class="line">  entityId<span class="token operator">=</span><span class="token string">&quot;player.entity&quot;</span></span>
<span class="line">  operation<span class="token operator">=</span><span class="token string">&quot;create&quot;</span></span>
<span class="line">  <span class="token comment">// 基于 player.entity.json 生成表单</span></span>
<span class="line">  <span class="token comment">// 调用 player.register 函数</span></span>
<span class="line"><span class="token operator">/</span><span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="🔗-api-接口" tabindex="-1"><a class="header-anchor" href="#🔗-api-接口"><span>🔗 API 接口</span></a></h2><h3 id="组件管理" tabindex="-1"><a class="header-anchor" href="#组件管理"><span>组件管理</span></a></h3><ul><li><code>GET /api/components</code> - 获取组件列表</li><li><code>POST /api/components/install</code> - 安装组件</li><li><code>DELETE /api/components/:id</code> - 卸载组件</li><li><code>POST /api/components/:id/enable</code> - 启用组件</li><li><code>POST /api/components/:id/disable</code> - 禁用组件</li></ul><h3 id="实体管理-已提供基础能力-待增强" tabindex="-1"><a class="header-anchor" href="#实体管理-已提供基础能力-待增强"><span>实体管理（已提供基础能力，待增强）</span></a></h3><ul><li><code>GET /api/v1/entities</code> - 获取实体列表</li><li><code>POST /api/v1/entities</code> - 创建新实体</li><li><code>GET /api/v1/entities/:id</code> - 获取实体详情</li><li><code>PUT /api/v1/entities/:id</code> - 更新实体定义</li><li><code>DELETE /api/v1/entities/:id</code> - 删除实体</li><li><code>GET /api/v1/entities/:id/preview</code> - 预览实体 UI</li><li><code>POST /api/v1/entities/validate</code> - 校验实体定义（JSON Schema）</li></ul><h3 id="函数调用" tabindex="-1"><a class="header-anchor" href="#函数调用"><span>函数调用</span></a></h3><ul><li><code>POST /api/invoke</code> - 调用函数</li><li><code>GET /api/v1/providers/descriptors</code> - 获取 Provider Manifest/统一描述符视图</li><li><code>GET /api/ui_schema</code> - 获取 UI Schema</li></ul><h2 id="🚀-实现状态" tabindex="-1"><a class="header-anchor" href="#🚀-实现状态"><span>🚀 实现状态</span></a></h2><h3 id="✅-已完成" tabindex="-1"><a class="header-anchor" href="#✅-已完成"><span>✅ 已完成</span></a></h3><ol><li><p><strong>组件管理系统</strong></p><ul><li>ComponentManager 实现</li><li>组件安装/卸载/启用/禁用</li><li>依赖关系检查</li><li>HTTP API 集成</li></ul></li><li><p><strong>玩家管理组件</strong></p><ul><li>完整的 CRUD 操作</li><li>实体定义 (player.entity.json)</li><li>资源配置 (player.resource.json)</li><li>所有函数描述符</li></ul></li><li><p><strong>物品管理组件</strong></p><ul><li>基础 CRUD 操作</li><li>实体定义 (item.entity.json)</li><li>资源配置 (item.resource.json)</li><li>部分函数描述符</li></ul></li><li><p><strong>经济系统组件</strong></p><ul><li>货币管理资源配置</li><li>基础架构</li></ul></li></ol><h3 id="🔄-进行中" tabindex="-1"><a class="header-anchor" href="#🔄-进行中"><span>🔄 进行中</span></a></h3><ol><li><strong>实体管理界面</strong><ul><li>可视化实体创建和编辑</li><li>JSON Schema 编辑器</li><li>UI 配置工具</li><li>预览功能</li></ul></li></ol><h3 id="📋-待实现" tabindex="-1"><a class="header-anchor" href="#📋-待实现"><span>📋 待实现</span></a></h3><p>详见 <code>server/todo.md</code>（按 P0/P1… 分级的未完成项汇总）。</p><h2 id="🎯-长期目标" tabindex="-1"><a class="header-anchor" href="#🎯-长期目标"><span>🎯 长期目标</span></a></h2><ol><li><p><strong>完整的低代码平台</strong></p><ul><li>拖拽式界面设计器</li><li>工作流编排</li><li>数据源连接器</li></ul></li><li><p><strong>多租户支持</strong></p><ul><li>租户级别的组件隔离</li><li>数据隔离</li><li>权限隔离</li></ul></li><li><p><strong>插件生态</strong></p><ul><li>第三方组件市场</li><li>组件模板库</li><li>社区贡献机制</li></ul></li></ol><hr><p>这个架构为游戏后台管理提供了强大的扩展性和可维护性，同时大大降低了新功能开发的门槛。</p>`,68)])])}const c=n(i,[["render",l]]),r=JSON.parse('{"path":"/ARCHITECTURE.html","title":"Croupier 对象驱动的组件化后台管理系统","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1766533527000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":2,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"8d5bb6849c1d80a3c68c5de32f59f854cc324a13","time":1766533527000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"P0/P1: proto-first generator, manifest, jobs routing, TLS"},{"hash":"faee2a3c8d1b9048fc593232ff61b9029e670933","time":1763217465000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"chore: migrate from submodule to monorepo architecture"}]},"filePathRelative":"ARCHITECTURE.md"}');export{c as comp,r as data};
